import { motion } from 'framer-motion';

type ListItem = { title: string; value: any };

interface Props {
  label?: string;
  items: Array<ListItem>;
  selectedValue: any;
  onChange: (item: ListItem) => void;
  initialValue?: any;
  Icon?: (props: any) => JSX.Element;
}

export default function AppButtonSelect({
  label,
  items,
  selectedValue,
  Icon,
  onChange,
}: Props) {
  function handleSelectionChange(item: ListItem) {
    onChange(item);
  }

  const isSelected = (value: any) => selectedValue === value;
  return (
    <div className='flex flex-row items-center gap-x-3'>
      {label && (
        <div className='flex-initial'>
          <p className='text-sm flex-initial w-max uppercase  overflow-hidden  opacity-50 border-r border-gray-400 pr-2  hover:text-sky-900'>
            {label}
          </p>
        </div>
      )}

      <div className=' grid grid-flow-col gap-2 flex-auto'>
        {items.map((item, index) => (
          <button
            key={index}
            type='button'
            className={`relative bg-gray-100  py-1 px-2 inline-flex gap-x-2 items-center justify-center  rounded-md  ${
              isSelected(item.value) ? ' text-white' : '  text-inherit'
            }`}
            onClick={() => handleSelectionChange(item)}
          >
            {isSelected(item.value) && (
              <motion.div
                layoutId={`${label}Highlight`}
                className=' z-[1] absolute top-0 left-0 right-0 bottom-0 bg-sky-500 rounded-md'
              ></motion.div>
            )}
            {Icon && <Icon className='  z-[2] h-5 w-5 text-inherit' />}
            <span className=' z-[2] relative font-Primary text-lg font-thin'>
              {item.title}
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}
